"""Provision Employee-role login accounts for Calling OS / CallNexa.

This script reuses the application's existing authentication model:

  * credentials live in ``public.users`` (bcrypt hash + EMPLOYEE role)
  * the employee profile lives in ``public.employees`` (linked by user_id)
  * IDs are generated by the existing database triggers

It deliberately does **not** create Supabase Auth users. The application
authenticates against ``public.users`` via FastAPI/JWT; ``auth.users`` is unused.

Password handling:
  * the temporary password is read from ``--password`` or the
    ``EMPLOYEE_TEMP_PASSWORD`` environment variable (or prompted for)
  * it is hashed with the application's own ``app/auth/password.py`` helper
  * it is never written to SQL, source control, or printed in the output

Usage (from the ``backend`` directory):

    set EMPLOYEE_TEMP_PASSWORD=<temporary-password>
    python provision_employees.py --org-code TZM-2026-7680

    # preview without writing
    python provision_employees.py --org-code TZM-2026-7680 --dry-run

The script is idempotent: if an account already exists it is reused. Existing
non-EMPLOYEE accounts are never modified, and existing passwords are never
reset unless ``--reset-passwords`` is explicitly supplied.
"""

from __future__ import annotations

import argparse
import getpass
import importlib.util
import os
import re
import sys
from dataclasses import dataclass
from pathlib import Path

from dotenv import load_dotenv

BASE_DIR = Path(__file__).resolve().parent

# Discover the same .env files the existing backend scripts use.
load_dotenv(BASE_DIR / ".env")
if not os.getenv("DATABASE_URL"):
    load_dotenv(BASE_DIR / ".env.production")

try:  # psycopg 3 is what requirements.txt pins
    import psycopg as pg  # type: ignore
except ImportError:  # local tooling often has psycopg2 only
    import psycopg2 as pg  # type: ignore


@dataclass(frozen=True)
class Account:
    email: str
    name: str


# The three employees requested for provisioning. Names are editable here; the
# e-mail address is the login identity and must stay unique.
ACCOUNTS: tuple[Account, ...] = (
    Account("k.vaibhavasri@gmail.com", "K Vaibhavasri"),
    Account("duvvuriravikanth2@gmail.com", "Duvvuri Ravikanth"),
    Account("harikakolanu67@gmail.com", "Harika Kolanu"),
)


def _load_password_helper():
    """Load app/auth/password.py without importing the rest of the app.

    Importing ``app.auth`` normally pulls in settings/JWT and requires the full
    runtime environment. Loading the module file directly keeps this script
    self-contained while still using the exact production hashing helpers.
    """
    path = BASE_DIR / "app" / "auth" / "password.py"
    spec = importlib.util.spec_from_file_location("callos_password", path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Could not load password helper from {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.hash_password, module.verify_password


def _normalise_db_url(url: str) -> str:
    """Convert a SQLAlchemy URL into a plain PostgreSQL URI for psycopg."""
    return (
        url.strip()
        .replace("postgresql+psycopg://", "postgresql://", 1)
        .replace("postgresql+psycopg2://", "postgresql://", 1)
    )


def _resolve_org(cur, org_code: str | None) -> tuple[str, str, str]:
    if org_code:
        cur.execute(
            """
            SELECT id, name, code
              FROM organizations
             WHERE UPPER(code) = UPPER(%s)
               AND status = 'active'
            """,
            (org_code.strip(),),
        )
        row = cur.fetchone()
        if not row:
            raise RuntimeError(f"No active organization found for code {org_code!r}")
        return row

    cur.execute(
        "SELECT id, name, code FROM organizations WHERE status = 'active' ORDER BY created_at"
    )
    rows = cur.fetchall()
    if len(rows) == 1:
        return rows[0]
    listing = ", ".join(f"{code} ({name})" for _, name, code in rows) or "none"
    raise RuntimeError(
        "Multiple active organizations found; pass --org-code. Available: " + listing
    )


def _next_employee_code(cur, org_id: str, reserved: set[str]) -> str:
    cur.execute(
        """
        SELECT employee_code
          FROM employees
         WHERE organization_id = %s
           AND employee_code ~ '^EMP[0-9]+$'
        """,
        (org_id,),
    )
    highest = 0
    for (code,) in cur.fetchall():
        match = re.fullmatch(r"EMP(\d+)", code or "")
        if match:
            highest = max(highest, int(match.group(1)))

    candidate = highest + 1
    while f"EMP{candidate:03d}" in reserved:
        candidate += 1
    return f"EMP{candidate:03d}"


def _find_users_by_email(cur, email: str):
    cur.execute(
        """
        SELECT id, organization_id, email, password_hash, role, status
          FROM users
         WHERE LOWER(email) = LOWER(%s)
        """,
        (email,),
    )
    return cur.fetchall()


def _find_employee_for_user(cur, user_id: str):
    cur.execute(
        """
        SELECT id, organization_id, user_id, name, email, employee_code, status
          FROM employees
         WHERE user_id = %s
        """,
        (user_id,),
    )
    return cur.fetchone()


def _find_employee_by_email(cur, org_id: str, email: str):
    cur.execute(
        """
        SELECT id, organization_id, user_id, name, email, employee_code, status
          FROM employees
         WHERE organization_id = %s
           AND LOWER(email) = LOWER(%s)
         ORDER BY created_at
        """,
        (org_id, email),
    )
    return cur.fetchall()


def _verify_password(verify_password, plain: str, hashed: str | None) -> bool:
    if not hashed:
        return False
    try:
        return bool(verify_password(plain, hashed))
    except Exception:
        return False


def provision(args) -> int:
    database_url = args.database_url or os.getenv("DATABASE_URL")
    if not database_url:
        raise RuntimeError("DATABASE_URL is required (or pass --database-url)")

    password = args.password or os.getenv("EMPLOYEE_TEMP_PASSWORD") or ""
    if not password:
        if args.dry_run:
            password = "__dry_run__"
        else:
            password = getpass.getpass("Temporary password for all three accounts: ")
    if not password:
        raise RuntimeError("A temporary password is required")

    hash_password, verify_password = _load_password_helper()

    conn = pg.connect(_normalise_db_url(database_url), connect_timeout=30)
    conn.autocommit = False
    try:
        with conn.cursor() as cur:
            org_id, org_name, org_code = _resolve_org(cur, args.org_code)
            print(f"Organization: {org_name} ({org_code}) -> {org_id}")

            results = []
            reserved_codes: set[str] = set()

            # Pre-reserve codes already attached to these accounts so a rerun
            # does not assign a duplicate code.
            for account in ACCOUNTS:
                users = _find_users_by_email(cur, account.email)
                if len(users) == 1:
                    employee = _find_employee_for_user(cur, users[0][0])
                    if employee:
                        reserved_codes.add(employee[5])

            for account in ACCOUNTS:
                users = _find_users_by_email(cur, account.email)

                if len(users) > 1:
                    raise RuntimeError(
                        f"{account.email} belongs to {len(users)} users across organizations; "
                        "email login would be ambiguous. Resolve manually before provisioning."
                    )

                if users:
                    user_id, user_org, user_email, pw_hash, role, status = users[0]
                    if user_org != org_id:
                        raise RuntimeError(
                            f"{account.email} already exists in a different organization "
                            f"({user_org}); refusing to move or duplicate it"
                        )
                    if (role or "").upper() != "EMPLOYEE":
                        raise RuntimeError(
                            f"{account.email} already exists with role {role!r}; refusing to "
                            "downgrade an existing account"
                        )
                    if status != "active":
                        raise RuntimeError(
                            f"{account.email} already exists but status is {status!r}; "
                            "reactivate it manually instead of changing its state here"
                        )

                    password_ok = _verify_password(verify_password, password, pw_hash)
                    if not password_ok:
                        if args.reset_passwords:
                            if not args.dry_run:
                                cur.execute(
                                    "UPDATE users SET password_hash = %s, updated_at = NOW() "
                                    "WHERE id = %s",
                                    (hash_password(password), user_id),
                                )
                            password_ok = True
                        else:
                            print(
                                f"  WARNING {account.email}: existing password does not match "
                                "the supplied temporary password (left unchanged; use "
                                "--reset-passwords to change it)"
                            )

                    employee = _find_employee_for_user(cur, user_id)
                    if employee:
                        emp_id, emp_org, _, _, emp_email, emp_code, emp_status = employee
                        if emp_org != org_id:
                            raise RuntimeError(
                                f"{account.email} is linked to an employee in another organization"
                            )
                        if not emp_email:
                            if not args.dry_run:
                                cur.execute(
                                    "UPDATE employees SET email = %s, updated_at = NOW() "
                                    "WHERE id = %s",
                                    (account.email, emp_id),
                                )
                            emp_email = account.email
                        action = "reused"
                        employee_status = emp_status
                    else:
                        # Legacy employee row with the same email but no user link.
                        by_email = _find_employee_by_email(cur, org_id, account.email)
                        if len(by_email) > 1:
                            raise RuntimeError(
                                f"Multiple employee profiles already use {account.email}; "
                                "resolve manually before provisioning"
                            )
                        if by_email:
                            emp_id = by_email[0][0]
                            if not args.dry_run:
                                cur.execute(
                                    "UPDATE employees SET user_id = %s, updated_at = NOW() "
                                    "WHERE id = %s",
                                    (user_id, emp_id),
                                )
                            emp_code = by_email[0][5]
                            employee_status = by_email[0][6]
                            action = "linked-existing-profile"
                        else:
                            emp_code = _next_employee_code(cur, org_id, reserved_codes)
                            reserved_codes.add(emp_code)
                            emp_id = None
                            employee_status = "active"
                            action = "created-profile"
                            if not args.dry_run:
                                cur.execute(
                                    """
                                    INSERT INTO employees
                                        (organization_id, user_id, name, email,
                                         employee_code, status)
                                    VALUES (%s, %s, %s, %s, %s, 'active')
                                    RETURNING id
                                    """,
                                    (org_id, user_id, account.name, account.email, emp_code),
                                )
                                emp_id = cur.fetchone()[0]

                    results.append(
                        {
                            "email": account.email,
                            "user_id": user_id,
                            "employee_id": emp_id,
                            "employee_code": emp_code,
                            "role": role,
                            "user_status": status,
                            "employee_status": employee_status,
                            "user_action": "reused",
                            "profile_action": action,
                            "password_ok": password_ok,
                        }
                    )
                    continue

                # Brand-new account.
                emp_code = _next_employee_code(cur, org_id, reserved_codes)
                reserved_codes.add(emp_code)
                user_id = None
                emp_id = None
                if not args.dry_run:
                    cur.execute(
                        """
                        INSERT INTO users
                            (organization_id, email, password_hash, role, status)
                        VALUES (%s, %s, %s, 'EMPLOYEE', 'active')
                        RETURNING id
                        """,
                        (org_id, account.email, hash_password(password)),
                    )
                    user_id = cur.fetchone()[0]

                    cur.execute(
                        """
                        INSERT INTO employees
                            (organization_id, user_id, name, email,
                             employee_code, status)
                        VALUES (%s, %s, %s, %s, %s, 'active')
                        RETURNING id
                        """,
                        (org_id, user_id, account.name, account.email, emp_code),
                    )
                    emp_id = cur.fetchone()[0]

                results.append(
                    {
                        "email": account.email,
                        "user_id": user_id,
                        "employee_id": emp_id,
                        "employee_code": emp_code,
                        "role": "EMPLOYEE",
                        "user_status": "active",
                        "employee_status": "active",
                        "user_action": "created",
                        "profile_action": "created-profile",
                        "password_ok": True,
                    }
                )

        if args.dry_run:
            conn.rollback()
            print("\nDRY RUN — no changes committed.\n")
        else:
            conn.commit()
            print("\nCommitted.\n")

        print(f"{'EMAIL':<34} {'USER ID':<32} {'EMP ID':<32} {'CODE':<7} ROLE")
        for r in results:
            print(
                f"{r['email']:<34} {str(r['user_id'] or '(dry-run)'):<32} "
                f"{str(r['employee_id'] or '(dry-run)'):<32} {r['employee_code']:<7} {r['role']}"
            )
        print()
        for r in results:
            print(
                f"{r['email']}: {r['user_action']} / {r['profile_action']}; "
                f"password={'ok' if r['password_ok'] else 'MISMATCH'}"
            )
        return 0
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--org-code",
        help="Organization code (for example TZM-2026-7680). Required if more than one active org.",
    )
    parser.add_argument(
        "--password",
        help="Temporary password (prefer EMPLOYEE_TEMP_PASSWORD to keep it out of shell history)",
    )
    parser.add_argument("--database-url", help="PostgreSQL URL; defaults to DATABASE_URL")
    parser.add_argument(
        "--reset-passwords",
        action="store_true",
        help="Reset the password of an existing EMPLOYEE account to the supplied temporary password",
    )
    parser.add_argument("--dry-run", action="store_true", help="Validate and roll back")
    return provision(parser.parse_args())


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(1)
